from __future__ import annotations
import math

def second_exponential_remainder(z: float) -> float:
    """Compute exp(z) - 1 - z with a series fallback near zero."""
    if abs(z) >= 1.0e-4:
        return math.expm1(z) - z
    term = z * z / 2.0
    total = term
    k = 2
    while k < 80:
        k += 1
        term *= z / k
        updated = total + term
        if updated == total:
            break
        total = updated
    return total

def evaluate_quadratic_approximant(width: int, x: float) -> float:
    if width < 1:
        raise ValueError("width must be positive")
    h = 1.0 / (width * width)
    return 2.0 * second_exponential_remainder(h * x) / (h * h)
